import {applicationWorkbook} from './excel-export.js';
import {levels,configs,newApplication,readApplication,totals,validation,fileStem,applicationCsv,rankingIndex} from './model.js';
import {importOrcid,importBib,fetchDoi,formatRecords} from './publications.js';
const $=id=>document.getElementById(id),key='rsa-applicant-flat-file-v1';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let deviceSave=false;
let app=newApplication(),step=1,candidates=[],chosen=new Set(),controller=null;
const matchRanking=rankingIndex(window.RSA_RANKINGS??{cabs:[],sjr:[]});
const titles=['','Details & request','Publications','Research activity','Plans & contribution','Review & save'];
const descriptions=['','Start with your details and the allowance you would like to request.','Choose the publications you want to include as evidence.','Record current work, REF readiness, funding, and supervision.','Describe your plans, research contribution, and impact.','Check the information and save a file to share through your university process.'];
const labels={mitigation:'Mitigating circumstances',phdSupervision:'PhD completions and supervision',futurePlans:'Current and future research and knowledge exchange plans',impact:'Contribution to impact'};
function message(text,error=false){$('message').textContent=text;$('message').classList.toggle('error',error);$('message').hidden=false;}
function persist(){app.updatedAt=new Date().toISOString();try{if(deviceSave)localStorage.setItem(key,JSON.stringify(app));$('saveStatus').textContent=(app.status==='Ready for review'?'Application saved on this device · ':'Draft saved on this device · ')+new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});}catch{$('saveStatus').textContent='Browser storage unavailable — save an application file';} if(!deviceSave)$('saveStatus').textContent='Draft in memory · download JSON to keep it';$('applicationStatus').textContent=app.status;}
function dirty(){$('fileReceipt').hidden=true;app.status='Draft';app.finalizedAt=null;app.declaration=false;$('declaration').checked=false;persist();renderTotals();if(step===5)renderReview();}
function download(text,filename,mime){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:mime}));a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function saveFile(){persist();download(JSON.stringify(app,null,2),fileStem(app)+'.json','application/json');message('Application file prepared for download. Keep this JSON file to reopen and continue later.');}
function showStep(n){step=Math.max(1,Math.min(5,n));document.querySelectorAll('.step-panel').forEach(p=>p.hidden=Number(p.dataset.step)!==step);document.querySelectorAll('[data-go]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.go)===step);if(Number(b.dataset.go)===step)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});$('stepEyebrow').textContent='STEP '+String(step).padStart(2,'0')+' / 05';$('stepTitle').textContent=titles[step];$('stepDescription').textContent=descriptions[step];$('back').hidden=step===1;$('next').hidden=step===5;if(step===5)renderReview();window.scrollTo({top:0,behavior:'instant'});$('stepTitle').tabIndex=-1;$('stepTitle').focus({preventScroll:true});}
function renderTotals(){const t=totals(app);$('totalHours').textContent=t.hours;$('fundingSummary').textContent=t.funding?'£'+t.funding.toLocaleString('en-GB')+' research allowance':'No funding selected';$('bidHoursSummary').textContent=t.rawBidHours>120?`Combined bid request: ${t.rawBidHours} hours; capped at 120 hours.`:`Combined PI and CI bid allowance: ${t.bidHours} hours (maximum 120).`;$('ecrYearRow').hidden=app.request.mainAllowance!=='125';document.querySelectorAll('[data-level]').forEach(b=>{b.classList.toggle('selected',b.dataset.level===app.request.mainAllowance);b.setAttribute('aria-pressed',String(b.dataset.level===app.request.mainAllowance));});}
function hydrate(){for(const el of document.querySelectorAll('[data-applicant]'))el.value=app.applicant[el.dataset.applicant]??'';for(const el of document.querySelectorAll('[data-answer]'))el.value=app.answers[el.dataset.answer]??'';$('piBid').value=String(app.request.piBid);$('ciBid').value=String(app.request.ciBid);$('rrAward').checked=app.request.rrAward;$('declaration').checked=app.declaration;$('orcidInput').value=app.applicant.orcid;renderTotals();renderPublications();for(const name of Object.keys(configs))renderTable(name);$('applicationStatus').textContent=app.status;}
function bindStatic(){
 $('mainAllowance').innerHTML=levels.map(l=>`<button type="button" data-level="${l.id}"><strong>${l.label}</strong><span>${l.description}</span><small>£${l.funding.toLocaleString('en-GB')}</small></button>`).join('');
 for(const b of document.querySelectorAll('[data-level]'))b.addEventListener('click',()=>{app.request.mainAllowance=b.dataset.level;if(b.dataset.level!=='125'){app.applicant.ecrYear='';$('ecrYear').value='';}dirty();});
 for(const el of document.querySelectorAll('[data-applicant]'))el.addEventListener('input',()=>{app.applicant[el.dataset.applicant]=el.value;dirty();});
 for(const el of document.querySelectorAll('[data-answer]'))el.addEventListener('input',()=>{app.answers[el.dataset.answer]=el.value;dirty();});
 for(const id of ['piBid','ciBid','rrAward'])$(id).addEventListener('change',()=>{app.request[id]=id==='rrAward'?$(id).checked:Number($(id).value);dirty();});
 for(const b of document.querySelectorAll('[data-go]'))b.addEventListener('click',()=>showStep(Number(b.dataset.go)));
 $('next').addEventListener('click',()=>showStep(step+1));$('back').addEventListener('click',()=>showStep(step-1));$('saveFile').addEventListener('click',saveFile);
 $('openFile').addEventListener('click',()=>$('resumeFile').click());
 $('resumeFile').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>10*1024*1024)throw new Error('Choose an application file smaller than 10 MB.');const restored=readApplication(JSON.parse(await file.text()));if(!window.confirm('Open this application in place of the current draft? Save the current JSON file first if you need to keep it.'))return;app=restored;$('fileReceipt').hidden=true;hydrate();persist();showStep(1);message('Opened '+file.name+'. You can continue editing this application.');}catch(error){message(error instanceof SyntaxError?'This is not a valid JSON application file.':error.message,true);}});
 $('newApplication').addEventListener('click',()=>{if(!confirm('Start a new application? Save your current application file first if you want to keep it.'))return;controller?.abort();app=newApplication();$('fileReceipt').hidden=true;candidates=[];chosen.clear();$('importResults').hidden=true;hydrate();persist();showStep(1);message('Started a new application.');});
 $('declaration').addEventListener('change',()=>{app.declaration=$('declaration').checked;app.status='Draft';app.finalizedAt=null;persist();});
 $('finish').addEventListener('click',async()=>{const errors=validation(app);$('validationErrors').hidden=!errors.length;if(errors.length){$('validationErrors').innerHTML='<strong>Please check:</strong><ul>'+errors.map(e=>'<li>'+escape(e)+'</li>').join('')+'</ul>';$('validationErrors').scrollIntoView({block:'center'});return;}const button=$('finish');button.disabled=true;try{const snapshot=structuredClone(app);snapshot.status='Ready for review';snapshot.finalizedAt=snapshot.updatedAt=new Date().toISOString();const bytes=await applicationWorkbook(snapshot);download(bytes,fileStem(snapshot)+'.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');app=snapshot;persist();renderReview();$('fileReceipt').hidden=false;$('fileReceipt').textContent='Your Excel application is ready for download. Upload it through your university process. Application ID: '+app.id+'. Nothing has been submitted from this app.';message('Excel file prepared. Save a JSON copy as well if you want to reopen and edit this application.');}catch(error){message('Excel export failed: '+error.message+'. Your draft is still available; save a JSON copy.',true);}finally{button.disabled=false;}});
 $('deviceSave').addEventListener('change',()=>{deviceSave=$('deviceSave').checked;try{localStorage.setItem(key+'-enabled',String(deviceSave));if(!deviceSave)localStorage.removeItem(key);}catch{}persist();});
 $('restoreDeviceDraft').addEventListener('click',()=>{try{const saved=localStorage.getItem(key);if(!saved)return;if(!confirm('Replace the current draft with the draft saved on this device?'))return;app=readApplication(JSON.parse(saved));hydrate();persist();message('Restored the draft saved on this device.');}catch(error){message(error.message,true);}});
 $('exportCsv').addEventListener('click',()=>{persist();download(applicationCsv(app),fileStem(app)+'.csv','text/csv;charset=utf-8');message('CSV prepared for download. Open it in Excel or another spreadsheet app; it contains one application row with all evidence sections.');});
 $('print').addEventListener('click',printApplication);
 for(const b of document.querySelectorAll('[data-add-row]'))b.addEventListener('click',()=>{addRow(b.dataset.addRow);});
 $('addManual').addEventListener('click',()=>{app.publications.push({id:crypto.randomUUID(),type:'article-journal',title:'',apa:'',journal:'',year:'',doi:'',issns:[],vreUrl:'',source:'Manual entry',issues:[],...matchRanking('')});dirty();renderPublications();});
 $('addRefPublication').addEventListener('click',()=>{const pub=app.publications.find(p=>p.id===$('refPublication').value);if(!pub||app.refOutputs.some(r=>r.publicationId===pub.id))return;app.refOutputs.push({id:crypto.randomUUID(),publicationId:pub.id,reference:pub.apa,refRating:'',openAccess:pub.vreUrl,ajg:pub.ajg,sjr:pub.sjr});dirty();renderTable('refOutputs');renderRefPicker();});
}
function publicationRank(pub){const row=[...document.querySelectorAll('[data-pub-id]')].find(el=>el.dataset.pubId===pub.id);if(row)row.querySelector('.metrics').textContent=`AJG 2024: ${pub.ajg} · SJR: ${pub.sjr}${pub.sjrQuartile?' · '+pub.sjrQuartile:''} · Match: ${pub.rankingMatch}`;}
function renderPublications(){
 $('publicationCount').textContent=app.publications.length+' included';$('emptyPublications').hidden=app.publications.length>0;
 $('publicationRows').innerHTML=app.publications.map((p,i)=>`<article class="publication-card" data-pub-id="${escape(p.id)}"><div class="section-heading compact"><h4>Publication ${i+1}</h4><button type="button" class="remove" data-remove-pub="${escape(p.id)}" aria-label="Remove publication ${i+1}">Remove</button></div><label>APA reference<textarea rows="3" data-pub-field="apa">${escape(p.apa)}</textarea></label><div class="form-grid three"><label>Type<select data-pub-field="type">${['article-journal','chapter','paper-conference','book','report','thesis','article','dataset','software'].map(t=>`<option ${t===p.type?'selected':''} value="${t}">${escape(t)}</option>`).join('')}</select></label><label>Publication year<input data-pub-field="year" value="${escape(p.year)}"></label><label>DOI<input data-pub-field="doi" value="${escape(p.doi)}"></label></div><div class="form-grid"><label>Journal / proceedings title<input list="journalNames" data-pub-field="journal" value="${escape(p.journal)}"></label><label>VRE / repository URL<input data-pub-field="vreUrl" value="${escape(p.vreUrl)}" placeholder="https://research.westminster.ac.uk/…"></label></div><p class="metrics">AJG 2024: ${escape(p.ajg)} · SJR: ${escape(p.sjr)}${p.sjrQuartile?' · '+escape(p.sjrQuartile):''} · Match: ${escape(p.rankingMatch)}</p>${p.issues.length?`<details class="publication-issues"><summary>Details to check in the imported reference</summary><ul>${p.issues.map(issue=>'<li>'+escape(issue)+'</li>').join('')}</ul></details>`:''}<small class="help">Source: ${escape(p.source)}</small></article>`).join('');
 for(const field of $('publicationRows').querySelectorAll('[data-pub-field]'))field.addEventListener('input',()=>{const pub=app.publications.find(p=>p.id===field.closest('[data-pub-id]').dataset.pubId);pub[field.dataset.pubField]=field.value;if(field.dataset.pubField==='journal'){pub.issns=[];Object.assign(pub,matchRanking(pub.journal));publicationRank(pub);}dirty();renderRefPicker();});
 for(const b of document.querySelectorAll('[data-remove-pub]'))b.addEventListener('click',()=>{app.publications=app.publications.filter(p=>p.id!==b.dataset.removePub);dirty();renderPublications();});renderRefPicker();
}
function renderRefPicker(){const used=new Set(app.refOutputs.map(r=>r.publicationId));const select=$('refPublication'),old=select.value;select.replaceChildren(new Option('Choose an included publication',''));for(const p of app.publications){const option=new Option(p.apa||'Untitled reference',p.id);option.disabled=used.has(p.id);select.add(option);}if(app.publications.some(p=>p.id===old)&&!used.has(old))select.value=old;$('addRefPublication').disabled=!select.value;}
$('refPublication').addEventListener('change',()=>$('addRefPublication').disabled=!$('refPublication').value);
function addRow(name){app[name].push({id:crypto.randomUUID(),...Object.fromEntries(configs[name].fields.map(([key])=>[key,'']))});dirty();renderTable(name);}
function renderTable(name){const config=configs[name],target=$(config.target);target.innerHTML=app[name].map((row,i)=>`<tr data-row-id="${escape(row.id)}">${config.fields.map(([field,label,type,options])=>{const a=`data-row-field="${field}" aria-label="${escape(label)} ${i+1}"`;if(type==='rank')return `<td data-rank="${field}">${escape(row[field]||'Not listed')}</td>`;if(type==='textarea')return `<td><textarea ${a} rows="3">${escape(row[field])}</textarea></td>`;if(type==='select')return `<td><select ${a}>${options.map(o=>`<option ${o===row[field]?'selected':''}>${escape(o)}</option>`).join('')}</select></td>`;return `<td><input ${a} ${type==='journal'?'list="journalNames"':''} value="${escape(row[field])}"></td>`;}).join('')}<td><button class="remove" data-remove-row="${escape(row.id)}" aria-label="Remove ${escape(config.title)} row ${i+1}">Remove</button></td></tr>`).join('');for(const field of target.querySelectorAll('[data-row-field]'))field.addEventListener('input',()=>{const tr=field.closest('tr'),row=app[name].find(r=>r.id===tr.dataset.rowId);row[field.dataset.rowField]=field.value;if(field.dataset.rowField==='journal'){const rank=matchRanking(field.value);row.ajg=rank.ajg;row.sjr=rank.sjr;for(const cell of tr.querySelectorAll('[data-rank]'))cell.textContent=row[cell.dataset.rank];}dirty();});for(const b of target.querySelectorAll('[data-remove-row]'))b.addEventListener('click',()=>{app[name]=app[name].filter(r=>r.id!==b.dataset.removeRow);dirty();renderTable(name);if(name==='refOutputs')renderRefPicker();});}
function renderReview(){const t=totals(app);$('reviewSummary').innerHTML=`<div class="review-grid"><div><span>Applicant</span><strong>${escape(app.applicant.name||'Not entered')}</strong><small>${escape(app.applicant.email||'Email not entered')}</small></div><div><span>School / year</span><strong>${escape(app.applicant.school||'Not selected')}</strong><small>${escape(app.applicant.academicYear)}</small></div><div><span>Total hours requested</span><strong>${t.hours}</strong><small>${t.baseHours} main + ${t.bidHours} bids + ${t.rrHours} R&R</small></div><div><span>Research allowance</span><strong>£${t.funding.toLocaleString('en-GB')}</strong><small>From your selected allowance level</small></div></div><dl class="review-counts"><dt>Publications included</dt><dd>${app.publications.length}</dd>${Object.entries(configs).map(([key,c])=>`<dt>${c.title}</dt><dd>${app[key].length}</dd>`).join('')}<dt>Future research plans</dt><dd>${app.answers.futurePlans.trim()?'Entered':'Not entered'}</dd><dt>Impact statement</dt><dd>${app.answers.impact.trim()?'Entered':'Not entered'}</dd></dl><p class="help">${app.publications.filter(p=>p.issues.length).length} imported references have details flagged for checking. This summary does not assess eligibility or decide an award.</p>`;}
function visibleCandidates(){const search=$('importSearch').value.toLowerCase().trim(),from=Number($('importFrom').value)||0,to=Number($('importTo').value)||9999;return candidates.filter(p=>(!search||p.apa.toLowerCase().includes(search))&&(!p.year||(Number(p.year)>=from&&Number(p.year)<=to)));}
function renderCandidates(){const visible=visibleCandidates();$('importList').innerHTML=visible.map(p=>`<label class="candidate"><input type="checkbox" data-candidate="${p.id}" ${chosen.has(p.id)?'checked':''}><span>${escape(p.apa)}<small>${escape(p.year||'No date')} · ${escape(p.type)} · AJG ${escape(p.ajg)}${p.issues.length?' · Check imported details':''}</small></span></label>`).join('')||'<p class="empty">No works match these filters.</p>';for(const c of $('importList').querySelectorAll('input'))c.addEventListener('change',()=>{if(c.checked)chosen.add(c.dataset.candidate);else chosen.delete(c.dataset.candidate);updateChosen();});$('importAll').checked=visible.length>0&&visible.every(p=>chosen.has(p.id));$('importAll').indeterminate=visible.some(p=>chosen.has(p.id))&&!$('importAll').checked;updateChosen();}
function updateChosen(){$('importSelected').textContent=chosen.size+' selected from '+candidates.length+' imported works';$('addImported').disabled=chosen.size===0;}
async function runImport(work){if(controller)return;controller=new AbortController();for(const id of ['loadOrcid','loadDoi','bibFile'])$(id).disabled=true;$('importStatus').textContent='Reading publications…';try{const {records,note=''}=await work(controller.signal);candidates=await formatRecords(records,matchRanking);chosen.clear();$('importResults').hidden=false;$('importHeading').textContent=`Choose publications to include (${candidates.length} found)`;$('importStatus').textContent=note||'Import complete. Select the works you want to include below.';$('importSearch').value='';renderCandidates();}catch(error){$('importStatus').textContent=error.name==='AbortError'?'Import cancelled.':error.name==='TimeoutError'?'The data service timed out. Please try again.':error.message||'Could not read the publications. Please try again.';}finally{controller=null;for(const id of ['loadOrcid','loadDoi','bibFile'])$(id).disabled=false;}}
$('loadOrcid').addEventListener('click',()=>runImport(async signal=>{const input=$('orcidInput').value;const records=await importOrcid(input,signal,text=>$('importStatus').textContent=text);return {records};}));
$('loadDoi').addEventListener('click',()=>runImport(async signal=>({records:[{item:await fetchDoi($('doiInput').value,signal),source:'DOI / Crossref',warnings:[]}]})));
$('bibFile').addEventListener('change',e=>{const file=e.target.files[0];e.target.value='';if(!file)return;runImport(async()=>{if(!/\.bib$/i.test(file.name)||!file.size||file.size>5*1024*1024)throw new Error('Choose a non-empty .bib file up to 5 MB.');const {records,duplicates}=importBib(await file.text());return {records,note:`Read ${file.name}${duplicates?`; combined ${duplicates} duplicate DOI entries`:''}. Select works to include below.`};});});
for(const id of ['importSearch','importFrom','importTo'])$(id).addEventListener('input',renderCandidates);
$('importAll').addEventListener('change',e=>{for(const p of visibleCandidates()){if(e.target.checked)chosen.add(p.id);else chosen.delete(p.id);}renderCandidates();});
$('closeImport').addEventListener('click',()=>{$('importResults').hidden=true;chosen.clear();});
$('addImported').addEventListener('click',()=>{const doiSet=new Set(app.publications.map(p=>p.doi.toLowerCase()).filter(Boolean));let added=0,duplicates=0;for(const p of candidates.filter(p=>chosen.has(p.id))){if(p.doi&&doiSet.has(p.doi.toLowerCase())){duplicates++;continue;}app.publications.push({...p});if(p.doi)doiSet.add(p.doi.toLowerCase());added++;}chosen.clear();dirty();renderPublications();renderCandidates();message(`${added} publications added${duplicates?`; ${duplicates} already included DOI records skipped`:''}. Check the references and add repository links where available.`);});
for(const tab of document.querySelectorAll('[data-tool]')){function activate(){for(const t of document.querySelectorAll('[data-tool]')){const selected=t===tab;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1;$(t.dataset.tool+'Tool').hidden=!selected;}}tab.addEventListener('click',activate);tab.addEventListener('keydown',e=>{const tabs=[...document.querySelectorAll('[data-tool]')];if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();tabs[(tabs.indexOf(tab)+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length].click();document.querySelector('[data-tool][aria-selected="true"]').focus();}});}
function printApplication(){const win=window.open('','_blank');if(!win){message('Allow the print window, then try again.',true);return;}const t=totals(app);const rows=Object.entries(app.applicant).map(([k,v])=>`<dt>${escape(k)}</dt><dd>${escape(v)}</dd>`).join('');const sections=Object.entries(configs).map(([key,c])=>`<h2>${escape(c.title)}</h2>${app[key].map(r=>'<p>'+c.fields.map(([f,label])=>`<strong>${escape(label)}:</strong> ${escape(r[f])}`).join('<br>')+'</p>').join('')||'<p>None entered</p>'}`).join('');win.document.write(`<!doctype html><meta charset="utf-8"><title>RSA application — ${escape(app.applicant.name)}</title><style>body{font:12px/1.6 Arial;max-width:850px;margin:35px auto;padding:20px}p,dd{white-space:pre-wrap;overflow-wrap:anywhere}h2{border-top:1px solid #ddd;padding-top:15px}dt{font-weight:bold}dd{margin:0 0 8px}p{break-inside:avoid}</style><h1>Research Support Allowance</h1><p>Application ${escape(app.id)} · ${escape(app.status)} · ${escape(app.applicant.academicYear)}</p><dl>${rows}</dl><h2>Allowance request</h2><p>Main: ${t.baseHours} hours; PI: ${app.request.piBid}; CI: ${app.request.ciBid}; combined bids after cap: ${t.bidHours}; R&R: ${t.rrHours}.<br>Total: ${t.hours} hours · £${t.funding}</p><h2>Publications</h2>${app.publications.map(p=>`<p>${escape(p.apa)}<br>AJG 2024: ${escape(p.ajg)} · SJR: ${escape(p.sjr)} · Match: ${escape(p.rankingMatch)}<br>DOI: ${escape(p.doi)}<br>VRE: ${escape(p.vreUrl)}</p>`).join('')||'<p>None entered</p>'}${sections}${Object.entries(labels).map(([k,label])=>`<h2>${escape(label)}</h2><p>${escape(app.answers[k])||'None entered'}</p>`).join('')}<h2>Declaration</h2><p>${app.declaration?'Confirmed':'Not confirmed'} · File only; no university submission was sent from this app.</p>`);win.document.close();win.focus();setTimeout(()=>win.print(),250);}
try{deviceSave=localStorage.getItem(key+'-enabled')==='true';const saved=localStorage.getItem(key);$('restoreDeviceDraft').hidden=!saved;if(saved&&deviceSave)app=readApplication(JSON.parse(saved));}catch{message('Browser storage is unavailable. Use JSON downloads to keep your draft.',true);}
$('deviceSave').checked=deviceSave;
bindStatic();hydrate();$('journalNames').innerHTML=(window.RSA_RANKINGS?.cabs??[]).map(r=>`<option value="${escape(r.title)}"></option>`).join('');

persist();
